class MinStack:
    """A stack that reports its smallest value."""

    def __init__(self):
        self._items = []
        self._mins = []

    def push(self, value):
        self._items.append(value)
        if not self._mins or value <= self._mins[-1]:
            self._mins.append(value)

    def pop(self):
        if not self._items:
            raise IndexError("pop from an empty stack")
        value = self._items.pop()
        if self._mins and value == self._mins[-1]:
            self._mins.pop()
        return value

    def top(self):
        if not self._items:
            raise IndexError("top from an empty stack")
        return self._items[-1]

    def get_min(self):
        if not self._items:
            raise ValueError("get_min from an empty stack")
        return self._mins[-1]

    def __len__(self):
        return len(self._items)
